            setA.add(resultMap.get(key));
        } else if (key.startsWith("B")) {
            setB.add(resultMap.get(key));
        }
    }

    // step 2: Add edges between all vertices in set A and set B
    for (V vertexA : setA) {
        for (V vertexB : setB) {
            target.addEdge(vertexA, vertexB);
        }
    }
}

