private static Type resolveRawType(Type type, Class<?> targetType) {
    if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        Type[] bounds = typeVariable.getBounds();
        if (bounds.length > 0) {
            return resolveRawType(bounds[0], targetType);
        }
        return Object.class; // default to Object if no bounds
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type rawType = parameterizedType.getRawType();
        if (rawType instanceof Class) {
            return rawType;
        }
        return resolveRawType(rawType, targetType);
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (upperBounds.length > 0) {
            return resolveRawType(upperBounds[0], targetType);
        }
        return Object.class; // default to Object if no upper bounds
    } else {
        return type;
    }
}

