static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 1000000000;
    long month = (timeBucket % 1000000000) / 1000000;
    long day = timeBucket % 1000000;

    if (dayStep == 1) {
        return timeBucket;
    }

    long newDay = day - (day % dayStep);
    if (newDay == 0) {
        newDay += dayStep;
        month -= 1;
    }
    if (month == 0) {
        month = 12;
        year -= 1;
    }
    long newMonth = month - (month % 1);

    return year * 1000000000 + newMonth * 1000000 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Round down the day to the nearest dayStep
    int newDay = (day - 1) / dayStep * dayStep + 1;

    // Ensure the day is not less than 1
    if (newDay < 1) {
        newDay = 1;
    }

    // Compress the time bucket with the new day
    return year * 10000 + month * 100 + newDay;
}

