static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    String timeStr = String.format("%08d", timeBucket);
    int year = Integer.parseInt(timeStr.substring(0, 4));
    int month = Integer.parseInt(timeStr.substring(4, 6));
    int day = Integer.parseInt(timeStr.substring(6, 8));

    int dayOfWeek = (int) (timeBucket % 7);
    int adjustedDay = day - (dayOfWeek + 7 - dayStep) % 7;

    if (adjustedDay < 1) {
        month -= 1;
        if (month == 0) {
            year -= 1;
            month = 12;
        }
        adjustedDay += dayInMonth(year, month);
    }

    return Long.parseLong(String.format("%04d%02d%02d", year, month, adjustedDay));
}

private static int dayInMonth(int year, int month) {
    switch (month) {
        case 2: return (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : 28;
        case 4: case 6: case 9: case 11: return 30;
        default: return 31;
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = (timeBucket / 10000000L) * 10000000L;
    long monthDay = timeBucket % 10000L;
    int dayOfMonth = (int) monthDay % 100;
    int newDayOfMonth = (dayOfMonth - 1) / dayStep * dayStep + 1;
    int newMonthDay = (int) monthDay - dayOfMonth + newDayOfMonth;
    return year + newMonthDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Invalid start index");
    }
    if (len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid length");
    }

    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if ((c & 0x7F) == c) {
            size += 1;
        } else if ((c & 0xE0) == 0xC0) {
            size += 2;
        } else if ((c & 0xF0) == 0xE0) {
            size += 3;
        } else if ((c & 0xF8) == 0xF0) {
            size += 4;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 character at index: " + (index + i));
        }
    }

    return size;
}

/**
 * Computes the size of the utf8 string beginning at the specified {@code index} with the specified {@code length}.
 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input CharSequence cannot be null");
    }

    if (index < 0 || len < 0 || (index + len) > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }

    int utf8Size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c <= 0x7F) {
            utf8Size += 1;
        } else if (c <= 0x7FF) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < len && Character.isLowSurrogate(str.charAt(index + i + 1))) {
            utf8Size += 4;
            i++; // Skip the low surrogate
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

