protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    for (E edge : edges) {
        E reverseEdge = graph.getEdge(edge.getTarget(), edge.getSource());
        if (reverseEdge != null && tour.contains(reverseEdge)) {
            // Skip reverse edges
            continue;
        }
        if (startVertex == null) {
            startVertex = edge.getSource();
            edges.add(0, edge); // Add the start edge at the beginning
        } else {
            edges.add(edge);
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("No valid start vertex found");
    }

    GraphPath<V,E> graphPath = new GraphPathImpl<>(graph, startVertex, edges, graph weightOf(edges));
    return graphPath;
}

private double weightOf(List<E> edges) {
    double weight = 0;
    for (E edge : edges) {
        weight += graph.getEdgeWeight(edge);
    }
    return weight;
}

GraphPath<V,E> function (Set<E> tour, Graph<V,E> graph) {
    List<E> pathEdges = new ArrayList<>(tour);
    V startVertex = null;
    for (E edge : pathEdges) {
        V vertex1 = graph.getEdgeSource(edge);
        V vertex2 = graph.getEdgeTarget(edge);
        if (startVertex == null) {
            startVertex = vertex1;
        }
        if (pathEdges.contains(graph.getEdge(vertex2, vertex1))) {
            pathEdges.remove(edge);
            pathEdges.add(graph.getEdge(vertex2, vertex1));
        } else {
            pathEdges.remove(edge);
            pathEdges.add(graph.getEdge(vertex1, vertex2));
        }
    }
    return new GraphWalk<>(graph, startVertex, startVertex, pathEdges, true);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Check for invalid inputs
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Create a list to store the path vertices
    List<V> pathVertices = new ArrayList<>();

    // Add the starting vertex from an arbitrary edge in the tour
    if (!tour.isEmpty()) {
        E edge = tour.iterator().next();
        V startVertex = graph.getEdgeSource(edge);
        pathVertices.add(startVertex);
    }

    // Reconstruct the tour by following the edges in the tour set
    for (E edge : tour) {
        V currentVertex = pathVertices.get(pathVertices.size() - 1);
        V nextVertex = graph.getEdgeTarget(edge);
        if (nextVertex.equals(currentVertex)) {
            nextVertex = graph.getEdgeSource(edge);
        }
        pathVertices.add(nextVertex);
    }

    // Create and return the graph path
    return graph.getPath(pathVertices);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return null;
    }
    Iterator<E> iterator = edgeList.iterator();
    V start = graph.getEdgeSource(iterator.next());
    List<V> nodes = new ArrayList<>();
    nodes.add(start);
    while (iterator.hasNext()) {
        E edge = iterator.next();
        V next = graph.getEdgeTarget(edge);
        if (nodes.get(nodes.size() - 1).equals(next)) {
            next = graph.getEdgeSource(edge);
        }
        nodes.add(next);
    }
    List<E> edges = new ArrayList<>();
    for (int i = 0; i < nodes.size() - 1; i++) {
        edges.add(graph.getEdge(nodes.get(i), nodes.get(i + 1)));
    }
    return new GraphPathImpl<>(graph, nodes, edges);
}

